import{_ as t,c as n,o as e,ag as r}from"./chunks/framework.CMajxlqO.js";const h=JSON.parse('{"title":"Koppling PLC ↔ HMI","description":"","frontmatter":{},"headers":[],"relativePath":"05-taggar/koppling-plc-hmi.md","filePath":"05-taggar/koppling-plc-hmi.md","lastUpdated":1768462574000}'),s={name:"05-taggar/koppling-plc-hmi.md"};function i(o,a,l,p,g,d){return e(),n("div",null,[...a[0]||(a[0]=[r(`<h1 id="koppling-plc-↔-hmi" tabindex="-1">Koppling PLC ↔ HMI <a class="header-anchor" href="#koppling-plc-↔-hmi" aria-label="Permalink to &quot;Koppling PLC ↔ HMI&quot;">​</a></h1><p>En av de mest kraftfulla funktionerna i TIA Portal är den <strong>integrerade</strong> kopplingen mellan PLC och HMI. Detta avsnitt förklarar hur du delar taggar och data mellan programlogik och operatörspanel.</p><h2 id="oversikt-plc-och-hmi-taggar" tabindex="-1">Översikt: PLC- och HMI-taggar <a class="header-anchor" href="#oversikt-plc-och-hmi-taggar" aria-label="Permalink to &quot;Översikt: PLC- och HMI-taggar&quot;">​</a></h2><h3 id="tre-typer-av-taggar-i-tia-portal" tabindex="-1">Tre typer av taggar i TIA Portal <a class="header-anchor" href="#tre-typer-av-taggar-i-tia-portal" aria-label="Permalink to &quot;Tre typer av taggar i TIA Portal&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tagg-typ</th><th>Var definieras</th><th>Var används</th><th>Kommunikation</th></tr></thead><tbody><tr><td><strong>PLC tags</strong></td><td>I PLC:n</td><td>PLC-program</td><td>Delas automatiskt till HMI</td></tr><tr><td><strong>HMI tags</strong></td><td>I HMI:n</td><td>Endast HMI-skärmar</td><td>Lokala variabler i HMI</td></tr><tr><td><strong>External tags</strong></td><td>Referens till PLC tags</td><td>HMI → PLC</td><td>Live-koppling till PLC-minne</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Bästa praxis</p><p><strong>Använd alltid PLC tags som &quot;External tags&quot; i HMI</strong> - då har du en gemensam tagg-databas och undviker synkroniseringsproblem.</p></div><h2 id="steg-for-steg-koppla-plc-till-hmi" tabindex="-1">Steg-för-steg: Koppla PLC till HMI <a class="header-anchor" href="#steg-for-steg-koppla-plc-till-hmi" aria-label="Permalink to &quot;Steg-för-steg: Koppla PLC till HMI&quot;">​</a></h2><h3 id="_1-skapa-plc-taggar" tabindex="-1">1. Skapa PLC-taggar <a class="header-anchor" href="#_1-skapa-plc-taggar" aria-label="Permalink to &quot;1. Skapa PLC-taggar&quot;">​</a></h3><p>Först definierar du taggarna i PLC:n.</p><p><strong>I PLC tags:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Namn                Datatyp    Adress    Kommentar</span></span>
<span class="line"><span>---------------------------------------------------</span></span>
<span class="line"><span>M01_Motor_Start     BOOL       %M0.0     Startkommando till motor 1</span></span>
<span class="line"><span>M01_Motor_Running   BOOL       %M0.1     Motor 1 körstatus</span></span>
<span class="line"><span>M01_Motor_Speed     INT        %MW10     Motor 1 hastighet (rpm)</span></span>
<span class="line"><span>Tank_Level          REAL       %MD20     Tanknivå (liter)</span></span>
<span class="line"><span>Alarm_Active        BOOL       %M1.0     Aktivt larm</span></span></code></pre></div><h3 id="_2-lagg-till-hmi-i-projektet" tabindex="-1">2. Lägg till HMI i projektet <a class="header-anchor" href="#_2-lagg-till-hmi-i-projektet" aria-label="Permalink to &quot;2. Lägg till HMI i projektet&quot;">​</a></h3><p>Om du inte redan har en HMI:</p><ol><li>Högerklicka <strong>Add new device</strong> → <strong>HMI</strong> → Välj modell (ex: KTP700 Basic)</li><li>Konfigurera <strong>Connection</strong> mellan PLC och HMI (Profinet PN/IE)</li></ol><h3 id="_3-importera-plc-taggar-till-hmi" tabindex="-1">3. Importera PLC-taggar till HMI <a class="header-anchor" href="#_3-importera-plc-taggar-till-hmi" aria-label="Permalink to &quot;3. Importera PLC-taggar till HMI&quot;">​</a></h3><p><strong>Automatisk import:</strong></p><ol><li>I HMI-projektträdet, gå till <strong>HMI tags</strong></li><li>Högerklicka <strong>Connections</strong> → Välj din PLC-koppling</li><li>Markera <strong>Default tag table</strong> i PLC</li><li>Dra och släpp till HMI-tag-området</li></ol><p><strong>Resultat:</strong> Alla PLC-taggar visas nu som <strong>External tags</strong> i HMI:n.</p><h3 id="_4-anvand-taggar-i-hmi-skarm" tabindex="-1">4. Använd taggar i HMI-skärm <a class="header-anchor" href="#_4-anvand-taggar-i-hmi-skarm" aria-label="Permalink to &quot;4. Använd taggar i HMI-skärm&quot;">​</a></h3><p><strong>Exempel: Knapp för motorstart</strong></p><ol><li>Öppna en HMI-skärm</li><li>Lägg till en <strong>Button</strong></li><li>Konfigurera Events: <ul><li><strong>Event:</strong> Press</li><li><strong>Function:</strong> SetBit</li><li><strong>Tag:</strong> <code>M01_Motor_Start</code></li></ul></li><li>Konfigurera Animation: <ul><li><strong>Property:</strong> Background color</li><li><strong>Tag:</strong> <code>M01_Motor_Running</code></li><li>TRUE = Grön, FALSE = Grå</li></ul></li></ol><p><strong>Exempel: Textfält för hastighetsvisning</strong></p><ol><li>Lägg till <strong>I/O Field</strong></li><li>Konfigurera: <ul><li><strong>Tag:</strong> <code>M01_Motor_Speed</code></li><li><strong>Format:</strong> Numeric, 4 digits</li><li><strong>Unit:</strong> &quot;rpm&quot;</li></ul></li></ol><h2 id="tagg-uppdateringslagen" tabindex="-1">Tagg-uppdateringslägen <a class="header-anchor" href="#tagg-uppdateringslagen" aria-label="Permalink to &quot;Tagg-uppdateringslägen&quot;">​</a></h2><h3 id="acquisition-mode" tabindex="-1">Acquisition Mode <a class="header-anchor" href="#acquisition-mode" aria-label="Permalink to &quot;Acquisition Mode&quot;">​</a></h3><p>Hur ofta HMI läser värden från PLC:n.</p><table tabindex="0"><thead><tr><th>Läge</th><th>Beskrivning</th><th>Användning</th></tr></thead><tbody><tr><td><strong>Cyclic continuous</strong></td><td>Läser kontinuerligt</td><td>Realtidsvärden (hastighet, tryck)</td></tr><tr><td><strong>Cyclic in operation</strong></td><td>Läser endast när skärm är aktiv</td><td>Energibesparing</td></tr><tr><td><strong>On demand</strong></td><td>Läser endast när begärt</td><td>Sällan ändrade värden</td></tr></tbody></table><p><strong>Sätta acquisition mode:</strong></p><ol><li>HMI tags → Högerklicka tagg → <strong>Properties</strong></li><li><strong>General</strong> → <strong>Acquisition mode</strong></li></ol><div class="tip custom-block"><p class="custom-block-title">Standard: Cyclic continuous</p><p>För de flesta fall, använd <strong>Cyclic continuous</strong> för snabb respons. Optimera endast om du har prestandaproblem.</p></div><h3 id="update-cycle" tabindex="-1">Update Cycle <a class="header-anchor" href="#update-cycle" aria-label="Permalink to &quot;Update Cycle&quot;">​</a></h3><p>Hur ofta värden uppdateras (millisekunder).</p><ul><li><strong>Standard:</strong> 100 ms (10 Hz)</li><li><strong>Snabb:</strong> 50 ms (20 Hz) - för snabba processer</li><li><strong>Långsam:</strong> 500-1000 ms - för trender och loggning</li></ul><p><strong>Sätta update cycle:</strong></p><ol><li>HMI tags → Markera taggar</li><li>Högerklicka → <strong>Properties</strong> → <strong>Acquisition cycle:</strong> 100 ms</li></ol><h2 id="datatyper-och-skalning" tabindex="-1">Datatyper och skalning <a class="header-anchor" href="#datatyper-och-skalning" aria-label="Permalink to &quot;Datatyper och skalning&quot;">​</a></h2><h3 id="direkt-koppling" tabindex="-1">Direkt koppling <a class="header-anchor" href="#direkt-koppling" aria-label="Permalink to &quot;Direkt koppling&quot;">​</a></h3><p>Datatyper som fungerar direkt mellan PLC och HMI:</p><table tabindex="0"><thead><tr><th>PLC-typ</th><th>HMI-typ</th><th>Exempel</th></tr></thead><tbody><tr><td>BOOL</td><td>Bool</td><td>Knappar, lampor</td></tr><tr><td>INT</td><td>Int</td><td>Hastighet, temperatur</td></tr><tr><td>REAL</td><td>Real</td><td>Flöde, tryck</td></tr><tr><td>STRING</td><td>String</td><td>Meddelanden, operatörsnamn</td></tr></tbody></table><h3 id="skalning-for-analoga-varden" tabindex="-1">Skalning för analoga värden <a class="header-anchor" href="#skalning-for-analoga-varden" aria-label="Permalink to &quot;Skalning för analoga värden&quot;">​</a></h3><p>Om PLC använder INT (ex: 0-27648 för 0-100%) måste du skala i HMI.</p><p><strong>Exempel: Analog ingång 0-27648 → 0-100%</strong></p><p><strong>I HMI:</strong></p><ol><li>Skapa <strong>Internal tag:</strong> <code>Tank_Level_Percent</code> (REAL)</li><li>I screen script eller cyclic update:</li></ol><div class="language-vbs vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vbs</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&#39; Skala 0-27648 till 0-100</span></span>
<span class="line"><span>Tag(&quot;Tank_Level_Percent&quot;) = (Tag(&quot;Tank_Level_Raw&quot;) / 27648.0) * 100.0</span></span></code></pre></div><p><strong>Eller använd Linear Scaling:</strong></p><ol><li>I/O Field → <strong>Properties</strong> → <strong>Representation</strong></li><li><strong>Linear scaling:</strong><ul><li>Process value min: 0</li><li>Process value max: 27648</li><li>Display value min: 0.0</li><li>Display value max: 100.0</li></ul></li></ol><h2 id="synkronisering-och-konsistens" tabindex="-1">Synkronisering och konsistens <a class="header-anchor" href="#synkronisering-och-konsistens" aria-label="Permalink to &quot;Synkronisering och konsistens&quot;">​</a></h2><h3 id="problem-dubbla-taggar" tabindex="-1">Problem: Dubbla taggar <a class="header-anchor" href="#problem-dubbla-taggar" aria-label="Permalink to &quot;Problem: Dubbla taggar&quot;">​</a></h3><p>❌ <strong>Fel:</strong> Skapa samma tagg i både PLC och HMI separat</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PLC tags: Motor_Speed (INT)</span></span>
<span class="line"><span>HMI tags: Motor_Speed (Int) - INTERN KOPIA</span></span></code></pre></div><p><strong>Resultat:</strong> Värden synkas inte automatiskt!</p><p>✅ <strong>Rätt:</strong> Använd PLC tags som External tags</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PLC tags: Motor_Speed (INT)</span></span>
<span class="line"><span>HMI external tags: Motor_Speed → PLC:Motor_Speed</span></span></code></pre></div><h3 id="automatisk-uppdatering" tabindex="-1">Automatisk uppdatering <a class="header-anchor" href="#automatisk-uppdatering" aria-label="Permalink to &quot;Automatisk uppdatering&quot;">​</a></h3><p>När du ändrar en PLC-tagg (namn, datatyp, kommentar):</p><ol><li><strong>Högerklicka</strong> i HMI tags → <strong>Update connection</strong></li><li>TIA Portal synkroniserar automatiskt</li></ol><div class="warning custom-block"><p class="custom-block-title">OBS</p><p>Om du tar bort en PLC-tagg som används i HMI får du <strong>kompileringsfel</strong>. Uppdatera alltid HMI efter PLC-ändringar!</p></div><h2 id="riktning-read-write-atkomst" tabindex="-1">Riktning: Read/Write-åtkomst <a class="header-anchor" href="#riktning-read-write-atkomst" aria-label="Permalink to &quot;Riktning: Read/Write-åtkomst&quot;">​</a></h2><h3 id="read-only-taggar" tabindex="-1">Read-only taggar <a class="header-anchor" href="#read-only-taggar" aria-label="Permalink to &quot;Read-only taggar&quot;">​</a></h3><p>För säkerhet, gör vissa taggar <strong>read-only</strong> i HMI.</p><p><strong>Exempel:</strong> Tanknivå får inte skrivas från HMI (endast läsas).</p><ol><li>HMI tags → Tagg <code>Tank_Level</code> → Properties</li><li><strong>Access mode:</strong> Read</li></ol><h3 id="write-only-taggar" tabindex="-1">Write-only taggar <a class="header-anchor" href="#write-only-taggar" aria-label="Permalink to &quot;Write-only taggar&quot;">​</a></h3><p>För känsliga värden (lösenord, parametrar).</p><ol><li>HMI tags → Tagg → Properties</li><li><strong>Access mode:</strong> Write</li></ol><div class="tip custom-block"><p class="custom-block-title">Standardinställning</p><p>Om inget anges är taggar <strong>Read/Write</strong>. Sätt restriktioner där det behövs för säkerhet.</p></div><h2 id="exempel-komplett-motorstyrning" tabindex="-1">Exempel: Komplett motorstyrning <a class="header-anchor" href="#exempel-komplett-motorstyrning" aria-label="Permalink to &quot;Exempel: Komplett motorstyrning&quot;">​</a></h2><h3 id="plc-tags-i-plc" tabindex="-1">PLC tags (i PLC) <a class="header-anchor" href="#plc-tags-i-plc" aria-label="Permalink to &quot;PLC tags (i PLC)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>M01_Start_Button     BOOL   %I0.0   &quot;Fysisk startknapp&quot;</span></span>
<span class="line"><span>M01_Stop_Button      BOOL   %I0.1   &quot;Fysisk stoppknapp&quot;</span></span>
<span class="line"><span>M01_Running          BOOL   %Q0.0   &quot;Motorutgång&quot;</span></span>
<span class="line"><span>M01_Speed_Setpoint   INT    %MW10   &quot;Hastighetsvärde från HMI (rpm)&quot;</span></span>
<span class="line"><span>M01_Speed_Actual     INT    %MW12   &quot;Faktisk hastighet från givare&quot;</span></span>
<span class="line"><span>M01_Alarm            BOOL   %M1.0   &quot;Motorlarm&quot;</span></span></code></pre></div><h3 id="hmi-skarm" tabindex="-1">HMI-skärm <a class="header-anchor" href="#hmi-skarm" aria-label="Permalink to &quot;HMI-skärm&quot;">​</a></h3><p><strong>Objekt 1: Startknapp</strong></p><ul><li>Type: Button</li><li>Event: Press → SetBit <code>M01_Start_Button</code></li><li>Animation: <code>M01_Running</code> → Grön (TRUE), Grå (FALSE)</li></ul><p><strong>Objekt 2: Stoppknapp</strong></p><ul><li>Type: Button</li><li>Event: Press → SetBit <code>M01_Stop_Button</code></li><li>Animation: Fast röd färg</li></ul><p><strong>Objekt 3: Hastighetsinställning</strong></p><ul><li>Type: I/O Field</li><li>Tag: <code>M01_Speed_Setpoint</code></li><li>Input: Enabled (användaren kan ändra)</li><li>Range: 0-1500 rpm</li></ul><p><strong>Objekt 4: Faktisk hastighet</strong></p><ul><li>Type: I/O Field</li><li>Tag: <code>M01_Speed_Actual</code></li><li>Input: Disabled (Read-only)</li><li>Format: &quot;0000 rpm&quot;</li></ul><p><strong>Objekt 5: Larmindikator</strong></p><ul><li>Type: Circle</li><li>Animation: <code>M01_Alarm</code> → Röd blinkande (TRUE), Osynlig (FALSE)</li></ul><h3 id="plc-program-i-ob1" tabindex="-1">PLC-program (i OB1) <a class="header-anchor" href="#plc-program-i-ob1" aria-label="Permalink to &quot;PLC-program (i OB1)&quot;">​</a></h3><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Motorlogik (förenklad)</span></span>
<span class="line"><span>IF &quot;M01_Start_Button&quot; AND NOT &quot;M01_Alarm&quot; THEN</span></span>
<span class="line"><span>    &quot;M01_Running&quot; := TRUE;</span></span>
<span class="line"><span>END_IF;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>IF &quot;M01_Stop_Button&quot; OR &quot;M01_Alarm&quot; THEN</span></span>
<span class="line"><span>    &quot;M01_Running&quot; := FALSE;</span></span>
<span class="line"><span>END_IF;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Hastighetsreglering (förenklad)</span></span>
<span class="line"><span>IF &quot;M01_Running&quot; THEN</span></span>
<span class="line"><span>    // Använd hastighetsvärde från HMI</span></span>
<span class="line"><span>    &quot;M01_Speed_Actual&quot; := &quot;M01_Speed_Setpoint&quot;;</span></span>
<span class="line"><span>END_IF;</span></span></code></pre></div><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Rekommendationer</p><ol><li><strong>Alltid PLC tags som källa:</strong> Definiera taggar i PLC, importera till HMI</li><li><strong>Konsekvent namngivning:</strong> <code>Device_Function_Property</code> (ex: <code>M01_Motor_Speed</code>)</li><li><strong>Kommentera allt:</strong> Kommentarer i PLC visas automatiskt i HMI</li><li><strong>Gruppera taggar:</strong> Använd flera tag tables (Inputs, Outputs, HMI_Variables)</li><li><strong>Update cycle:</strong> 100 ms för realtid, 500-1000 ms för loggning</li><li><strong>Read-only där möjligt:</strong> Lås taggar som HMI inte ska ändra</li><li><strong>Testa koppling:</strong> Använd <strong>Online &amp; Diagnostics</strong> för att verifiera kommunikation</li></ol></div><h2 id="felsokning-kommunikationsproblem" tabindex="-1">Felsökning: Kommunikationsproblem <a class="header-anchor" href="#felsokning-kommunikationsproblem" aria-label="Permalink to &quot;Felsökning: Kommunikationsproblem&quot;">​</a></h2><h3 id="problem-taggar-uppdateras-inte" tabindex="-1">Problem: Taggar uppdateras inte <a class="header-anchor" href="#problem-taggar-uppdateras-inte" aria-label="Permalink to &quot;Problem: Taggar uppdateras inte&quot;">​</a></h3><p><strong>Checklista:</strong></p><ol><li>✅ Är HMI och PLC <strong>online</strong>? (Grön ikon i projektträdet)</li><li>✅ Är <strong>connection</strong> korrekt konfigurerad? (Profinet/Ethernet)</li><li>✅ Har du <strong>uppdaterat HMI tags</strong> efter PLC-ändringar?</li><li>✅ Är acquisition mode <strong>Cyclic continuous</strong>?</li><li>✅ Kör programmet både i PLC och HMI? (Download till båda)</li></ol><h3 id="problem-fel-datatyp" tabindex="-1">Problem: Fel datatyp <a class="header-anchor" href="#problem-fel-datatyp" aria-label="Permalink to &quot;Problem: Fel datatyp&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PLC: Motor_Speed (REAL)</span></span>
<span class="line"><span>HMI: Motor_Speed (Int)</span></span></code></pre></div><p><strong>Lösning:</strong> Uppdatera HMI tags eller konvertera i PLC/HMI.</p><h2 id="resurser" tabindex="-1">Resurser <a class="header-anchor" href="#resurser" aria-label="Permalink to &quot;Resurser&quot;">​</a></h2><ul><li><a href="https://support.industry.siemens.com/cs/document/109742726/plc-hmi-communication-basics" target="_blank" rel="noreferrer">Siemens: PLC-HMI Communication (PDF)</a></li><li><a href="https://www.youtube.com/watch?v=n3QbOk7nP3Y" target="_blank" rel="noreferrer">Video: Connecting HMI to PLC</a></li><li><a href="https://www.youtube.com/watch?v=dQw4w9WgXcQ" target="_blank" rel="noreferrer">Video: HMI Tag Management</a></li><li><a href="./../06-kommunikation/profinet.html">Nästa: Profinet-kommunikation →</a></li></ul><hr><p><strong>Relaterat:</strong></p><ul><li><a href="./../07-hmi-design/skarmbilder.html">HMI-design och skärmar</a></li><li><a href="./globala-lokala.html">Globala vs lokala taggar</a></li><li><a href="./../03-konfiguration/hmi-installningar.html">Konfiguration av HMI</a></li></ul>`,97)])])}const u=t(s,[["render",i]]);export{h as __pageData,u as default};
